'use strict';
state.resultFilter='success';
function resultStatus(record){return ['success','failure','unknown'].includes(record?.result_status)?record.result_status:'unknown';}
function resultCases(db){return (db.cases||[]).filter(c=>state.resultFilter==='all'||resultStatus(c)===state.resultFilter);}
function resultLabel(status){return {success:'成功 / Success',failure:'失败 / Failure',unknown:'未评分 / Unscored',all:'全部 / All'}[status]||'未评分 / Unscored';}
function installResultFilter(){if(!$('#result-filter')){const box=document.createElement('div');box.className='sr-result-filter';box.innerHTML='<label for="result-filter">Result / 结果</label><select id="result-filter"><option value="success">成功 / Success</option><option value="all">全部 / All</option><option value="failure">失败 / Failure</option><option value="unknown">未评分 / Unscored</option></select><div id="result-filter-count" class="sr-note"></div>';$('#db-search').before(box);$('#result-filter').onchange=()=>{state.resultFilter=$('#result-filter').value;stop();if(state.case&&resultStatus(state.case)!==state.resultFilter&&state.resultFilter!=='all'){state.epoch++;state.case=null;}drawDatabases();drawQuery();};$('#archiveSelect').addEventListener('change',()=>{stop();if(state.case&&state.resultFilter!=='all'&&resultStatus(state.case)!==state.resultFilter)state.case=null;drawDatabases();drawQuery();});}$('#result-filter').value=state.resultFilter;drawDatabases();}
drawDatabases=function(){if(!state.catalog)return;const query=$('#db-search').value.toLowerCase(),all=state.catalog.databases.flatMap(db=>db.cases||[]);const groups=state.catalog.databases.map(db=>{const matchDB=displayDatabase(db.id).toLowerCase().includes(query);const cases=resultCases(db).filter(c=>!query||matchDB||[c.id,c.question].join(' ').toLowerCase().includes(query));return {db,cases,keep:!query||matchDB||cases.length};}).filter(g=>g.keep);const shown=groups.reduce((n,g)=>n+g.cases.length,0);const counts=all.reduce((sum,c)=>(sum[resultStatus(c)]++,sum),{success:0,failure:0,unknown:0});if($('#result-filter-count'))$('#result-filter-count').textContent=`显示 ${shown} / ${all.length} · 成功 ${counts.success} · 失败 ${counts.failure} · 未评分 ${counts.unknown}`;$('#list').innerHTML=groups.map(({db,cases})=>`<details class="sr-db-tree" ${state.db?.database===db.id?'open':''}><summary class="dbhdr ${state.db?.database===db.id?'open sel':''}" data-db="${esc(db.id)}"><span class="caret">▶</span><span class="dbn">${esc(displayDatabase(db.id))}</span><span class="cnt">${cases.length}/${db.cases.length} Q</span></summary><div class="sr-db-count">${db.columns} columns · ${db.sources} source records</div>${cases.length?cases.map(c=>`<button class="item task ${state.case?.id===c.id?'sel':''}" data-case="${esc(c.id)}" data-case-db="${esc(db.id)}" data-result-status="${resultStatus(c)}"><span class="id">${esc(c.id)}</span><span class="sr-tree-question">${esc(c.question)}</span><span class="sr-tag sr-result-${resultStatus(c)}">${esc(resultLabel(resultStatus(c)))}</span></button>`).join(''):`<div class="empty sr-empty-small">${esc(resultLabel(state.resultFilter))} · 0 questions</div>`}</details>`).join('');document.querySelectorAll('[data-db]').forEach(row=>row.onclick=async event=>{event.preventDefault();if(state.db?.database===row.dataset.db){row.closest('details').open=!row.closest('details').open;return;}await selectDatabase(row.dataset.db);});document.querySelectorAll('[data-case]').forEach(row=>row.onclick=async()=>{const db=row.dataset.caseDb,id=row.dataset.case;const entry=state.catalog.databases.find(d=>d.id===db);if(!entry||!resultCases(entry).some(c=>c.id===id))return;if(state.db?.database!==db)await selectDatabase(db);if(state.db?.database===db)await selectCase(id);});};
const queryBeforeResultFilter=drawQuery;
drawQuery=function(){if(state.case&&state.case.origin!=='archive'&&!state.case.result_status){state.case.result_status='unknown';state.resultFilter='unknown';if($('#result-filter'))$('#result-filter').value='unknown';if(state.catalog)drawDatabases();}queryBeforeResultFilter();if(state.case){const badge=$('#query .badge');if(badge)badge.textContent=(state.case.origin==='archive'?'Saved archive · ':'Local API · ')+resultLabel(resultStatus(state.case));}else if(state.db){const badge=$('#query .badge');if(badge)badge.textContent=`${resultCases(state.db).length}/${state.db.cases.length} · ${resultLabel(state.resultFilter)}`;}};
if(state.catalog)installResultFilter();
